file.content:
    # no pending marker references it). Multi-file restore groups are
    # resolved later by the RestoreCoordinator, which reaps their
    # journals itself.
    self._recover_provisions()

# -- provider helpers --------------------------------------------------
@staticmethod
def _provider():
    """The active KMS/HSM provider (imported lazily on first use)."""
    return provider_mod.get_provider()

# -- provision journal -------------------------------------------------
# An import/restore attempt mints provider objects (handles) *before* its
# conflict recheck, file writes and the durable audit append. The journal
# records every minted handle as it appears and is removed only after the
# attempt finishes (commit or clean rollback). A process killed in between
# is cleaned up at the next open: handles whose committing audit event is
# in the ledger stay; every other handle is deleted, idempotently.
_PROVISION_DIR = "provisions"

def _provision_path(self, journal_id: str) -> str:
    return os.path.join(
        self.data_dir, self._PROVISION_DIR, journal_id + ".json"
    )

def _new_provision_journal(self, journal_id: str):
    """Create one journal file for an import/restore attempt.

    The journal is named after the attempt's audit ``event_id``: a
    leftover journal can then be resolved at any startup by asking the
    ledger whether that event committed — committed means keep every
    handle, otherwise delete them. Returns (journal_id, path). A crash
    before the journal exists simply means no handles were recorded yet.
    """
    directory = os.path.join(self.data_dir, self._PROVISION_DIR)
    os.makedirs(directory, exist_ok=True)
    path = self._provision_path(journal_id)
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    os.close(fd)
    return journal_id, path

def _append_provision(self, path: str, provider_id: str, handle: str) -> None:
    """Durably record one minted handle in an attempt's journal."""
    entry = {"provider_id": provider_id, "handle": handle}
    line = json.dumps(entry, separators=(",", ":")) + "\n"
    with open(path, "a", encoding="utf-8") as fh:
        fh.write(line)
        fh.flush()
        os.fsync(fh.fileno())

def _discard_provision_journal(self, path: str) -> bool:
    """Drop an attempt's journal after it committed or rolled back.

    Returns True when the journal is gone (including an already-absent
    one); a removal failure leaves the journal in place for the next
    open's recovery sweep instead of being silently swallowed.
    """
    try:
        os.unlink(path)
        return True
    except FileNotFoundError:
        return True
    except OSError:
        return False

def _delete_provisioned_handle(self, provider_id: str, handle: str) -> bool:
    """Delete one uncommitted handle. Returns True on success.

    A cleanup failure is never silently swallowed: False keeps the
    attempt's provision journal on disk so the next open retries the
    delete. Crash cleanup may need the local backend before any request
    configured it (this never imports an external module:factory
    provider); a missing/inactive provider whose handle cannot be reached
    is likewise reported, not hidden.
    """
    if provider_id == LOCAL_PROVIDER_ID:
        try:
            provider_mod.configure_local(self.data_dir)
        except ProviderUnavailable:
            return False
    try:
        provider = self._provider_for(provider_id)
    except ProviderUnavailable:
        return False
    try:
        provider.delete(handle)
    except Exception:
        return False
    return True

def _restore_marker_journals(self) -> set:
    """Journal ids referenced by still-present outbox markers.

    A multi-file restore transaction is resolved by the
    RestoreCoordinator and a multi-key batch-rotation group by
    _recover_batch_rotations; their journals must not be reaped here even
    if its shared event is not in the ledger yet (the coordinator/group
    recovery either commits and keeps the handles, or rolls the whole
    group back and deletes them). A single-key rotate/import marker
    carrying a journal is deferred as well whenever its ledger append
    could not be settled earlier in this same open: deleting its handles
    before the event is durable would orphan the record the next open
    commits. Markers can live on a key file or, for a policy-only restore,
    in the policies directory.
    """
    referenced = set()

    def consider(marker) -> None:
        if not isinstance(marker, dict):
            return
        journal_id = marker.get("journal")
        if isinstance(journal_id, str) and journal_id:
            referenced.add(journal_id)

    try:
        names = os.listdir(self.data_dir)
    except OSError:
        names = []
    for name in names:
        if name.endswith(".json") and is_valid_key_id(name[:-5]):
            record = self._read_record(os.path.join(self.data_dir, name))
            if record is not None:
                consider(record.pending_event)
    policy_dir = os.path.join(self.data_dir, "policies")
    try:
        policy_names = os.listdir(policy_dir)
    except OSError:
        policy_names = []
    for name in policy_names:
        if not name.endswith(".json"):
            continue
        try:
            with open(
                os.path.join(policy_dir, name), "r", encoding="utf-8"
            ) as fh:
                doc = json.load(fh)
        except (OSError, ValueError):
            continue
        if isinstance(doc, dict):
            consider(doc.get("pending_event"))
    return referenced

def _rollback_provision_entries(self, entries) -> bool:
    """Delete handles recorded by an uncommitted attempt.

    Returns True only when every handle was deleted (or its provider
    cannot be reached but is not local — see _delete_provisioned_handle);
    a single failed delete means False and the journal must be retained
    for a retry on the next open. Deletes stay idempotent.
    """
    cleaned = True
    for provider_id, handle in entries:
        if not self._delete_provisioned_handle(provider_id, handle):
            cleaned = False
    return cleaned

def _recover_provisions(self) -> None:
    """Settle provision journals left by attempts that did not finish.

    Resolution is driven purely by the ledger event named after the
    journal (the operation/event id):

    * a durable ``success`` event is the commit point -- the minted
      handles are now owned by the records and stay, the journal is
      removed;
    * no event, or a durable ``rejected`` event (a bound provider-failure
      terminal), means the attempt never owned the handles -- every
      recorded handle is deleted idempotently and the journal is removed
      only once every delete succeeds;
    * an unreadable ledger, a non-UUID journal or a failed handle delete
      leaves everything in place for the next open.

    Journals still referenced by a restore marker are deferred to the
    RestoreCoordinator. Nothing here imports a provider when there are no
    handles to reap, so opening a store for plain reads stays
    provider-free.
    """
    deferred = (
        self._restore_marker_journals()
        | self.batch_recovery_journal_ids()
    )
    directory = os.path.join(self.data_dir, self._PROVISION_DIR)
    try:
        names = os.listdir(directory)
    except OSError:
        return
    for name in names:
        if not name.endswith(".json"):
            continue
        journal_id = name[:-5]
        if journal_id in deferred:
            continue
        path = os.path.join(directory, name)
        try:
            with open(path, "r", encoding="utf-8") as fh:
                lines = fh.readlines()
        except OSError:
            continue
        entries = []
        for line in lines:
            line = line.strip()
            if not line:
                continue
            try:
                entry = json.loads(line)
            except ValueError:
                continue
            if not isinstance(entry, dict):
                continue
            provider_id = entry.get("provider_id")
            handle = entry.get("handle")
            if isinstance(provider_id, str) and provider_id and isinstance(
                handle, str
            ) and handle:
                entries.append((provider_id, handle))
        try:
            is_uuid4 = uuid.UUID(journal_id).version == 4
        except (ValueError, AttributeError):
            # An unidentifiable journal can never be resolved against an
            # event: leave it for manual/operator resolution rather than
            # deleting possibly-committed material.
            continue
        if not is_uuid4:
            continue
        event = None
        try:
            event = self.audit.get_event(journal_id)
        except LedgerError:
            # Cannot decide right now; leave the whole journal for a
            # later open rather than deleting committed material.
            continue
        if event is not None and event.outcome == audit_mod.OUTCOME_SUCCESS:
            # Committed: handles belong to the durable records; housekeep
            # the journal. A failed unlink simply retries on next open.
            self._discard_provision_journal(path)
            continue
        # Event absent (crash/rollback) or a durable rejected terminal:
        # the attempt never owned the handles. Retain the journal until
        # every handle delete actually succeeds.
        if self._rollback_provision_entries(entries):
            self._discard_provision_journal(path)

def drop_provision_journal(self, journal_id: str) -> bool:
    """Remove an attempt journal after it committed or fully rolled back.

    Returns True when no journal remains. A failed unlink keeps it for
    startup recovery.
    """
    if not journal_id:
        return True
    return self._discard_provision_journal(self._provision_path(journal_id))

def rollback_provision_journal(self, journal_id: str) -> bool:
    """Delete every handle an uncommitted attempt journaled, then drop it.

    Used by the request path when an import/rotate/restore aborts before
    its commit point (provider fault, refused conflict, ledger failure).
    The journal is removed only once every recorded handle has been
    deleted; a failed backend delete retains it so the next open retries
    — cleanup failures are reported, never swallowed. Idempotent.
    """
    if not journal_id:
        return True
    entries = self.read_provision_journal(journal_id)
    if not self._rollback_provision_entries(entries):
        return False
    return self.drop_provision_journal(journal_id)

def _abort_provision(self, journal_id: str, adopted=()) -> None:
    """Scrub handles of an aborted attempt and reconcile its journal.

    Deletes the still-known ``(provider, handle)`` pairs directly and then
    the durable journal (which covers handles whose entries were recorded
    but whose in-memory pair the aborting frame no longer holds); deletes
    are idempotent. Raises ProviderUnavailable when any delete cannot be
    verified -- the journal then stays on disk and startup retries -- so a
    cleanup failure is a 503, never a silent orphan.
    """
    cleaned = self._release_handles(adopted)
    if not self.rollback_provision_journal(journal_id):
        cleaned = False
    if not cleaned:
        raise ProviderUnavailable(
            "could not delete a handle provisioned by an aborted attempt; "
            "cleanup will be retried at startup"
        )

def read_provision_journal(self, journal_id: str) -> list:
    """Return the (provider_id, handle) pairs an attempt journal holds."""
    if not journal_id:
        return []
    path = self._provision_path(journal_id)
    entries = []
    try:
        with open(path, "r", encoding="utf-8") as fh:
            lines = fh.readlines()
    except OSError:
        return []
    for line in lines:
        line = line.strip()

    self._idempotent_guard(
        parts.path, tenant_id, operator, payload, idem_key, execute
    )

def _parse_batch_items(self, raw):
    """Validate a batch-rotate items array before the key is bound.

    Thin HTTP wrapper over the shared, side-effect-free validator so
    the CLI and the service accept exactly the same items shape.
    """
    return validate_batch_items(raw)

def _batch_rotate_keys(self, parts, operator: str) -> None:
    """POST /v1/keys/batch-rotate.

    The Idempotency-Key is checked before the body is read. Every
    parse/parameter/items failure is a side-effect-free 400 (no audit
    event, operation record, key change or provider handle) and never
    consumes the key. After binding, authorization follows the
    ``rotate`` action (a denial is a terminal 403 whose single
    rejected ``batch_rotate`` event has key_id null); any unknown or
    foreign key_id makes the whole batch a terminal 404 with zero
    changes. On success every key gains one fresh version under the
    rotate semantics, the batch commits atomically, and the response
    items are in request order.
    """
    idem_key = self._idempotency_key()
    if idem_key is None:
        return
    payload = self._read_json_object(audit=False)
    if payload is None:
        return
    body_tenant = payload.get("tenant_id")
    if not isinstance(body_tenant, str) or not body_tenant:
        self._bad_request("field tenant_id must be a non-empty string")
        return
    tenant_id = self._tenant(parts, payload, audit=False)
    if tenant_id is None:
        return
    items, error = self._parse_batch_items(payload.get("items"))
    if error is not None:
        self._bad_request(error)
        return

    def execute(operation):
        # Kind and the exact request-order item set are durable before
        # any business check, so a 403/404 terminal replays from
        # context alone after a crash.
        operation_store.update_details(
            operation,
            {
                "kind": "batch_rotate",
                "items": [
                    {"key_id": key_id, "algorithm": algorithm}
                    for key_id, algorithm in items
                ],
            },
        )
        # Authorization follows rotate and precedes existence; a
        # denial is a bound terminal 403 with one rejected
        # batch_rotate event (key_id null).
        if not policy_store.is_allowed(
            tenant_id, audit_mod.ACTION_ROTATE, operator
        ):
            return self._idempotent_rejection(
                operation, tenant_id, None,
                audit_mod.ACTION_BATCH_ROTATE, 403,
                "action not permitted by policy",
            )

        def stage_success(records_by_id):
            # After every key file landed, before the single
            # commit-point append: stage the exact 201 body verbatim,
            # with items in REQUEST order.
            result_items = [
                {
                    "key_id": key_id,
                    "version": records_by_id[key_id].current.version,
                    "algorithm": records_by_id[key_id].current.algorithm,
                    "public_key": records_by_id[key_id].current.public_key,
                }
                for key_id, _ in items
            ]
            operation_store.stage_terminal(
                operation,
                201,
                {
                    "items": result_items,
                    "operation_id": operation.operation_id,
                },
            )

        status, result = store.batch_rotate(
            tenant_id, items,
            event_id=operation.operation_id,
            lock_timeout=operations_mod.LOCK_WAIT_SECONDS,
            pre_commit=stage_success,
        )
        if status == store.BATCH_NOT_FOUND:
            # Any unknown/foreign key_id fails the whole batch with no
            # change; the answer is identical to a missing key so
            # cross-tenant existence never leaks.
            return self._idempotent_rejection(
                operation, tenant_id, None,
                audit_mod.ACTION_BATCH_ROTATE, 404, "key not found",
            )
        result_items = [
            {
                "key_id": key_id,
                "version": record.current.version,
                "algorithm": record.current.algorithm,
                "public_key": record.current.public_key,
            }
            for key_id, record in result
        ]
        # The single success event committed with the files.
        return 201, {"items": result_items}

    self._idempotent_guard(
        parts.path, tenant_id, operator, payload, idem_key, execute
    )

def _revoke_key(self, key_id: str, parts, operator: str) -> None:
    payload = self._read_json_object()
    if payload is None:
        return
    body_tenant = payload.get("tenant_id")
    if not isinstance(body_tenant, str) or not body_tenant:
        # The body must itself carry a non-empty tenant_id.
        if not self._record_conflict():
            return
        self._bad_request("field tenant_id must be a non-empty string")
        return
    tenant_id = self._tenant(parts, payload)
    if tenant_id is None:
        return
    if self._bad_key_id(key_id):
        return
    for field in ("reason", "operator"):
        value = payload.get(field)
        if not isinstance(value, str) or not value:
            if not self._record_attempt(
                tenant_id, key_id, audit_mod.ACTION_REVOKE,
                audit_mod.OUTCOME_REJECTED,
            ):
                return
            self._bad_request(
                "field %s must be a non-empty string" % field
                if value is not None
                else "missing required field: %s" % field
            )
            return
    if not self._enforce(
        tenant_id, key_id, audit_mod.ACTION_REVOKE, operator
    ):
        return
    record = store.revoke(
        key_id, tenant_id, payload["reason"], payload["operator"]
    )
    if record is None:
        if not self._record_attempt(
            tenant_id, key_id, audit_mod.ACTION_REVOKE,
            audit_mod.OUTCOME_REJECTED,
        ):
            return
        self._send_json(404, {"error": "key not found"})
        return
    self._send_json(200, record.to_status_response())

def _export_key(self, key_id: str, parts, operator: str) -> None:
    """POST /v1/keys/{key_id}/export.

    The body must carry a non-empty tenant_id and passphrase; an
    X-Tenant-Id header or ?tenant_id= may supplement the body but
    must agree with it. The full record (including private material)
    is only ever returned sealed inside the opaque bundle.
    """
    payload = self._read_json_object()
    if payload is None:
        return
    body_tenant = payload.get("tenant_id")
    if not isinstance(body_tenant, str) or not body_tenant:
        if not self._record_conflict():
            return
        self._bad_request("field tenant_id must be a non-empty string")
        return
    tenant_id = self._tenant(parts, payload)
    if tenant_id is None:
        return
    if self._bad_key_id(key_id):
        return
    passphrase = payload.get("passphrase")
    if not isinstance(passphrase, str) or not passphrase:
        if not self._record_attempt(
            tenant_id, key_id, audit_mod.ACTION_EXPORT,
            audit_mod.OUTCOME_REJECTED,
        ):
            return
        self._bad_request(
            "field passphrase must be a non-empty string"
        )
        return
    if not self._enforce(
        tenant_id, key_id, audit_mod.ACTION_EXPORT, operator
    ):
        return
    # The record is read before the success event, but nothing is
    # persisted by an export, so a ledger failure after this point
    # simply fails the request with 500.
    bundle = store.export_bundle(key_id, tenant_id, passphrase)
    if bundle is None:
        # Unknown key and another tenant's key look identical.
        if not self._record_attempt(
            tenant_id, key_id, audit_mod.ACTION_EXPORT,
            audit_mod.OUTCOME_REJECTED,
        ):
            return
        self._send_json(404, {"error": "key not found"})
        return
    if not self._record_attempt(
        tenant_id, key_id, audit_mod.ACTION_EXPORT,
        audit_mod.OUTCOME_SUCCESS,
    ):
        return
    self._send_json(
        200, {"format": keybundle.FORMAT, "bundle": bundle}
    )

def _import_key(self, parts, operator: str) -> None:
    """POST /v1/keys/import.

    The Idempotency-Key is checked before the body is even read.
    Every subsequent parse/decrypt/parameter failure is a
    side-effect-free 400 (no audit event, no operation record, no
    provider handle) and never consumes the key. Once the key is
    bound, a policy denial / unknown key / conflict is a terminal
    state whose single rejection event is named after the
    operation_id. A key_id the tenant already owns is a 409 that
    leaves the original record untouched; the same key_id owned by
    another tenant answers 404 so existence never leaks across
    tenants.
    """
    idem_key = self._idempotency_key()
    if idem_key is None:
        return
    payload = self._read_json_object(audit=False)
    if payload is None:
        return
    body_tenant = payload.get("tenant_id")
    if not isinstance(body_tenant, str) or not body_tenant:
        self._bad_request("field tenant_id must be a non-empty string")
        return
    tenant_id = self._tenant(parts, payload, audit=False)
    if tenant_id is None:
        return
    passphrase = payload.get("passphrase")
    if not isinstance(passphrase, str) or not passphrase:
        self._bad_request(
            "field passphrase must be a non-empty string"
        )
        return
    bundle = payload.get("bundle")
    if not isinstance(bundle, str) or not bundle:
        self._bad_request("field bundle must be a non-empty string")
        return
    # An already-bound key replays/conflicts before we decrypt, so a
    # wrong passphrase on a retry neither masks a replay nor consumes
    # the key.
    if self._idempotent_precheck(
        parts.path, tenant_id, operator, payload, idem_key
    ):
        return
    # Decrypting/authenticating the bundle is side-effect free, so it
    # stays outside the idempotent binding: a wrong passphrase or a
    # tampered bundle is a plain 400 with no audit event and never
    # consumes the key.
    try:
        decoded = keybundle.decode_bundle(bundle, passphrase)
    except keybundle.BundleError as exc:
        self._bad_request(str(exc))

def _get_key(self, key_id: str, parts, operator: str) -> None:
    tenant_id = self._tenant(parts)
    if tenant_id is None:
        return
    if self._bad_key_id(key_id):
        return
    if not self._enforce(
        tenant_id, key_id, audit_mod.ACTION_READ, operator
    ):
        return
    record = store.get(key_id, tenant_id)
    if record is None:
        # Same status whether the key is missing or owned by another
        # tenant: never confirm the existence of another tenant's key.
        self._reject_read(tenant_id, key_id, 404, "key not found")
        return
    if not self._record_attempt(
        tenant_id, key_id, audit_mod.ACTION_READ,
        audit_mod.OUTCOME_SUCCESS,
    ):
        return
    self._send_json(200, record.to_get_response())

def _get_version(self, key_id: str, raw_version: str, parts,
                 operator: str) -> None:
    tenant_id = self._tenant(parts)
    if tenant_id is None:
        return
    if self._bad_key_id(key_id):
        return
    version = self._parse_version(raw_version)
    if version is None:
        # Bad version parameter: tenant and key are known, so the
        # rejection is visible to them.
        self._reject_read(
            tenant_id, key_id, 400,
            "field version must be a positive integer",
        )
        return
    if not self._enforce(
        tenant_id, key_id, audit_mod.ACTION_READ, operator
    ):
        return
    result = store.get_version(key_id, tenant_id, version)
    if result is None:
        # Unknown key, unknown version and cross-tenant access are
        # indistinguishable, all 404.
        self._reject_read(
            tenant_id, key_id, 404, "version not found"
        )
        return
    if not self._record_attempt(
        tenant_id, key_id, audit_mod.ACTION_READ,
        audit_mod.OUTCOME_SUCCESS,
    ):
        return
    _record, ver = result
    self._send_json(200, ver.to_version_response(key_id))

def _get_current(self, key_id: str, parts, operator: str) -> None:
    tenant_id = self._tenant(parts)
