def _marker_event_durable(self, marker) -> bool:
    """True when a pending marker's event already reached the ledger.

    Markers carry the event nested under ``"event"`` (the multi-file
    shapes) or flat (single-key outbox). An unreadable ledger is treated
    as not durable.
    """
    if not isinstance(marker, dict):
        return False
    nested = marker.get("event")
    desc = nested if isinstance(nested, dict) else marker
    event_id = desc.get("event_id") if isinstance(desc, dict) else None
    if not isinstance(event_id, str) or not event_id:
        return False
    try:
        return self.audit.get_event(event_id) is not None
    except LedgerError:
        return False

